package dev.eugheist.tc4modern;
import java.util.*;import java.util.function.Supplier;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.alchemy.*;import net.minecraft.core.registries.*;import thaumcraft.api.aspects.Aspect;
/** Original variant tables and value-splitting dice algorithm, with modern item/potion identities. */
public final class PechTrades {
 private record Entry(int tier,Supplier<ItemStack> item){}
 public static int value(ItemStack stack){if(stack.isEmpty())return 0;if(stack.getItem() instanceof ManaBeanItem)return 1;if(stack.is(Items.GOLD_INGOT)||stack.is(Items.GOLDEN_APPLE)||stack.is(Items.ENCHANTED_GOLDEN_APPLE))return 2;if(stack.is(Items.ENDER_PEARL))return 3;if(stack.is(Items.DIAMOND))return 4;if(stack.is(Items.EMERALD))return 5;var id=BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();return Math.min(32,Math.max(AspectTable.get(id).getOrDefault(Aspect.GREED.getTag(),0),ModernAspectCatalog.get("items",id).getOrDefault(Aspect.GREED.getTag(),0)));}
 static ItemStack mod(String name){var id=AlchemyContent.id(name);if(!BuiltInRegistries.ITEM.containsKey(id))throw new IllegalStateException("Missing original Pech reward: "+id);return new ItemStack(BuiltInRegistries.ITEM.get(id));}
 private static void add(List<Entry> list,int tier,Item item){list.add(new Entry(tier,()->new ItemStack(item)));}
 private static void mod(List<Entry> list,int tier,String item){list.add(new Entry(tier,()->mod(item)));}
 private static void potion(List<Entry> list,int tier,net.minecraft.core.Holder<Potion> potion){list.add(new Entry(tier,()->PotionContents.createItemStack(Items.POTION,potion)));}
 private static void book(List<Entry> list,int tier,net.minecraft.resources.ResourceKey<net.minecraft.world.item.enchantment.Enchantment> enchant,Player player){list.add(new Entry(tier,()->{var stack=new ItemStack(Items.ENCHANTED_BOOK);stack.enchant(player.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(enchant),1);return stack;}));}
 private static List<Entry> inventory(int variant,Player player){var list=new ArrayList<Entry>();mod(list,1,"mana_bean");if(variant==0){for(String name:List.of("iron_cluster","gold_cluster","cinnabar_cluster","copper_cluster"))mod(list,1,name);add(list,2,Items.BLAZE_ROD);add(list,2,TC4Modern.GREATWOOD_SAPLING.get().asItem());potion(list,2,Potions.STRENGTH);potion(list,2,Potions.SWIFTNESS);add(list,3,Items.EXPERIENCE_BOTTLE);mod(list,3,"knowledge_fragment");add(list,3,Items.GOLDEN_APPLE);potion(list,3,Potions.LONG_STRENGTH);potion(list,3,Potions.LONG_NIGHT_VISION);add(list,5,Items.ENCHANTED_GOLDEN_APPLE);mod(list,4,"thaumium_pickaxe");mod(list,5,"silverwood_sapling");mod(list,5,"silverwood_sapling");}else if(variant==1){for(String name:List.of("air","fire","water","earth","order","entropy"))mod(list,1,name+"_shard");mod(list,1,"knowledge_fragment");mod(list,2,"knowledge_fragment");potion(list,2,Potions.REGENERATION);potion(list,2,Potions.HEALING);book(list,3,BasicsEnchantments.HASTE,player);add(list,3,Items.GOLDEN_APPLE);potion(list,3,Potions.STRONG_REGENERATION);potion(list,3,Potions.STRONG_HEALING);for(var cluster:BasicsContent.CLUSTERS)add(list,4,cluster.get().asItem());add(list,5,Items.ENCHANTED_GOLDEN_APPLE);book(list,5,BasicsEnchantments.REPAIR,player);for(String name:List.of("focus_pouch","focus_pech","vis_amulet_lesser"))mod(list,5,name);}else{for(int i=0;i<15;i++)mod(list,1,"candle_"+i);add(list,2,Items.GHAST_TEAR);potion(list,2,Potions.SWIFTNESS);potion(list,2,Potions.STRENGTH);book(list,2,net.minecraft.world.item.enchantment.Enchantments.POWER,player);add(list,3,Items.EXPERIENCE_BOTTLE);mod(list,3,"knowledge_fragment");potion(list,3,Potions.LONG_INVISIBILITY);potion(list,3,Potions.STRONG_REGENERATION);add(list,3,Items.GOLDEN_APPLE);add(list,5,Items.ENCHANTED_GOLDEN_APPLE);mod(list,4,"thaumium_boots");mod(list,5,"runic_ring_lesser");book(list,5,net.minecraft.world.item.enchantment.Enchantments.FLAME,player);book(list,5,net.minecraft.world.item.enchantment.Enchantments.INFINITY,player);}return list;}
 static void trade(PechEntity pech,SimpleContainer slots,Player player){var random=pech.getRandom();int value=value(slots.getItem(0));if(random.nextInt(100)<=value/2){pech.tamed(false);pech.playSound(net.minecraft.sounds.SoundEvent.createVariableRangeEvent(AlchemyContent.id("pech_trade")),.4f,1);}if(random.nextInt(5)==0)value+=random.nextInt(3);else if(random.nextBoolean())value-=random.nextInt(3);var list=inventory(pech.variant(),player);while(value>0){int tier=Math.min(5,Math.max((value+1)/2,random.nextInt(value)+1));value-=tier;ItemStack reward=null;var carried=new ArrayList<Integer>();for(int i=0;i<9;i++)if(!pech.loot.getItem(i).isEmpty())carried.add(i);if(tier==1&&random.nextBoolean()&&!carried.isEmpty()){reward=pech.loot.removeItem(carried.get(random.nextInt(carried.size())),1);}else if(tier>=4&&random.nextBoolean())reward=dungeonReward(player,random);else{int chosenTier=tier;var choices=list.stream().filter(e->e.tier==chosenTier).toList();reward=choices.get(random.nextInt(choices.size())).item.get();}insert(slots,reward);}slots.removeItem(0,1);}
 static ItemStack dungeonReward(Player player,net.minecraft.util.RandomSource random){Item[] rare={Items.GOLDEN_APPLE,Items.MUSIC_DISC_13,Items.MUSIC_DISC_CAT,Items.GOLDEN_HORSE_ARMOR,Items.IRON_HORSE_ARMOR,Items.DIAMOND_HORSE_ARMOR,Items.ENCHANTED_BOOK};var item=rare[random.nextInt(rare.length)];var stack=new ItemStack(item);if(item==Items.ENCHANTED_BOOK){var candidates=player.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.tags.EnchantmentTags.ON_RANDOM_LOOT).stream().toList();var chosen=candidates.get(random.nextInt(candidates.size()));stack.enchant(chosen,net.minecraft.util.Mth.nextInt(random,chosen.value().getMinLevel(),chosen.value().getMaxLevel()));}return stack;}
 private static void insert(SimpleContainer slots,ItemStack stack){for(int i=1;i<5;i++){var there=slots.getItem(i);if(!there.isEmpty()&&ItemStack.isSameItemSameComponents(there,stack)){int n=Math.min(stack.getCount(),there.getMaxStackSize()-there.getCount());there.grow(n);stack.shrink(n);}}for(int i=1;i<5&&!stack.isEmpty();i++)if(slots.getItem(i).isEmpty())slots.setItem(i,stack.split(stack.getMaxStackSize()));slots.setChanged();}
}
